//! OUTPUT relList is a SameObject DOMTokenList with ordinary PutForwards.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><form id=owner><label id=label for=output>Result</label><area id=output rel='first second first' class=stable><input id=first value=first><input id=second value=second></form><div id=mount></div></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://area-rel-list.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn area_rel_list_canonical_descriptor_same_object_native_list_and_distinct_brand(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var output=document.getElementById('output'),d=Object.getOwnPropertyDescriptor(HTMLAreaElement.prototype,'relList');if(!d||typeof d.get!=='function'||typeof d.set!=='function'||!d.enumerable||!d.configurable||d.get.name!=='get relList'||d.get.length!==0||d.set.name!=='set relList'||d.set.length!==1||Object.hasOwn(output,'relList'))throw 'canonical output token descriptor';var tokens=output.relList;if(tokens!==output.relList||tokens!==d.get.call(output)||tokens===output.classList||Object.getPrototypeOf(tokens)!==DOMTokenList.prototype||!(tokens instanceof DOMTokenList)||Object.prototype.toString.call(tokens)!=='[object DOMTokenList]'||tokens.value!=='first second first'||tokens.length!==2||tokens[0]!=='first'||tokens.item(1)!=='second'||tokens.item(2)!==null||tokens[2]!==undefined||Object.keys(tokens).join(',')!=='0,1'||Array.from(tokens).join(',')!=='first,second')throw 'actual native SameObject for tokens';var caught=false;if(tokens.supports('noopener')||tokens.supports('noreferrer')||tokens.supports('opener')||tokens.supports('unknown'))throw 'unimplemented processing tokens not advertised';for(var bad of [{},Object.create(HTMLAreaElement.prototype),document.getElementById('label'),document.createElement('div'),document.createElementNS('urn:foreign','area')]){caught=false;try{d.get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'genuine output token brand';}"#);}
#[test]
fn area_rel_list_exact_tokens_mutate_for_without_class_or_label_authority(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var output=document.getElementById('output'),tokens=output.relList,classes=output.classList;output.setAttribute('rel','A\ud800z A�z A\ud800z');if(tokens.length!==2||tokens[0]!=='A\ud800z'||!tokens.contains('A\ud800z')||!tokens.contains('A�z'))throw 'exact source token units';tokens.remove('A�z');tokens.add('B\udfffz','B\udfffz');if(tokens.value!=='A\ud800z B\udfffz'||!tokens.replace('A\ud800z','C\ud800z')||tokens.value!=='C\ud800z B\udfffz')throw 'exact token serialization';if(tokens.toggle('B\udfffz')||!tokens.toggle('D\ud800z',true)||tokens.value!=='C\ud800z D\ud800z')throw 'exact toggle';if(output.getAttribute('rel')!==tokens.value||output.relList!==tokens||output.classList!==classes||classes.value!=='stable')throw 'independent native attributes and label authority';"#);}
#[test]
fn area_rel_list_put_forwards_uses_ordinary_get_before_target_value_conversion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var output=document.getElementById('output'),d=Object.getOwnPropertyDescriptor(HTMLAreaElement.prototype,'relList'),tokens=output.relList,order=[];d.set.call(output,{toString:function(){order.push('convert');return 'A\ud800z';}});if(tokens.value!=='A\ud800z'||order.join(',')!=='convert')throw 'native value setter conversion';var target={},value={marker:true},seen;Object.defineProperty(target,'value',{set:function(v){order.push('target');seen=v;},configurable:true});Object.defineProperty(output,'relList',{get:function(){order.push('get');return target;},configurable:true});order=[];d.set.call(output,value);if(order.join(',')!=='get,target'||seen!==value||tokens.value!=='A\ud800z')throw 'ordinary Get then target Set with original value';Object.defineProperty(output,'relList',{get:function(){return 7;},configurable:true});var calls=0,caught=false;try{d.set.call(output,{toString:function(){calls++;return 'bad';}});}catch(e){caught=e instanceof TypeError;}if(!caught||calls||tokens.value!=='A\ud800z')throw 'primitive forward target before conversion';delete output.relList;output.relList='fresh';if(output.relList!==tokens||tokens.value!=='fresh')throw 'restored inherited forwarding';"#);}

#[test]
fn area_rel_list_forwards_original_value_after_author_get_and_ignores_failed_set(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
'use strict';var subject=document.getElementById('output'),descriptor=Object.getOwnPropertyDescriptor(HTMLAreaElement.prototype,'relList'),order='',value={toString:function(){order+='convert';return 'bad';}},seen,receiver;var target={set value(v){order+='set';seen=v;receiver=this;}};Object.defineProperty(subject,'relList',{get:function(){order+='get';return target;},configurable:true});if(descriptor.set.call(subject,value)!==undefined||order!=='getset'||seen!==value||receiver!==target||subject.getAttribute('rel')!=='first second first')throw 'original forwarded value';var symbol=Symbol();descriptor.set.call(subject,symbol);if(seen!==symbol)throw 'symbol passed unchanged';Object.defineProperty(target,'value',{value:'fixed',writable:false,configurable:true});descriptor.set.call(subject,value);if(target.value!=='fixed')throw 'nonwritable';Object.defineProperty(target,'value',{get:function(){return 'readonly';},configurable:true});descriptor.set.call(subject,value);if(target.value!=='readonly')throw 'getter only';var proxy=new Proxy({}, {set:function(t,k,v,r){if(k!=='value'||v!==value||r!==proxy)throw 'trap args';return false;}});target=proxy;descriptor.set.call(subject,value);target=Object.preventExtensions({});descriptor.set.call(subject,value);if(Object.hasOwn(target,'value'))throw 'nonextensible';target=3;try{descriptor.set.call(subject,value);throw 'primitive target';}catch(e){if(!(e instanceof TypeError))throw e;}var marker={};Object.defineProperty(subject,'relList',{get:function(){throw marker;},configurable:true});try{descriptor.set.call(subject,value);throw 'getter abrupt';}catch(e){if(e!==marker)throw e;}target={set value(v){throw marker;}};Object.defineProperty(subject,'relList',{get:function(){return target;},configurable:true});try{descriptor.set.call(subject,value);throw 'setter abrupt';}catch(e){if(e!==marker)throw e;}if(order.indexOf('convert')!==-1)throw 'premature conversion';delete subject.relList;subject.relList='recovered';if(subject.getAttribute('rel')!=='recovered')throw 'native recovery';
"#);}

#[test]
fn area_rel_list_live_iteration_observation_and_validation_keep_actual_for_record(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var output=document.getElementById('output'),t=output.relList,a=output.getAttributeNode('rel'),watch=new MutationObserver(function(){});watch.observe(output,{attributes:true,attributeOldValue:true});t.toggle('first',true);t.replace('missing','last');if(watch.takeRecords().length||t.value!=='first second first')throw 'no-op preserves spelling and observation';t.value='A\ud800z A�z';t.remove('A�z');var records=watch.takeRecords();if(records.length!==2||records[0].oldValue!=='first second first'||records[1].oldValue!=='A\ud800z A�z'||records[1].attributeName!=='rel'||records[1].attributeNamespace!==null||a!==output.getAttributeNode('rel')||a.value!==t.value)throw 'actual record observations';t.value='one two';var iterator=t.values();if(iterator.next().value!=='one')throw 'iterator first';t.add('three');if(iterator.next().value!=='two'||iterator.next().value!=='three'||!iterator.next().done)throw 'live native iterator';var seen=[];t.forEach(function(v,i,list){if(list!==t)throw 'callback list';seen.push(v);if(i===0)t.remove('two');});if(seen.join(',')!=='one,three')throw 'live callback';var calls='';try{t.add('',{toString:function(){calls+='convert';output.setAttribute('rel','callback');return 'late';}});throw 'missing validation';}catch(e){if(e.name!=='SyntaxError')throw e;}if(calls!=='convert'||t.value!=='callback')throw 'conversion before validation';var marker={};try{t.value={toString:function(){output.setAttribute('rel','effect');throw marker;}};throw 'missing abrupt';}catch(e){if(e!==marker)throw e;}if(t.value!=='effect')throw 'completed author effects';"#);}
#[test]
fn area_rel_list_inert_clone_adoption_no_main_slots_and_typed_handle_guards(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=document.implementation.createHTMLDocument('source'),source=owner.createElement('area');source.relList='A\ud800z A�z';var list=source.relList,copy=source.cloneNode(true),copied=copy.relList,attr=copy.getAttributeNode('rel'),target=document.implementation.createHTMLDocument('target');target.adoptNode(copy);target.body.appendChild(copy);copied.remove('A�z');copied.add('B\udfffz');if(String(copied)!=='A\ud800z B\udfffz'||copied.item(1)!=='B\udfffz'||Array.from(copied).join(',')!=='A\ud800z,B\udfffz'||copy.relList!==copied||list===copied||copied.value!=='A\ud800z B\udfffz'||list.value!=='A\ud800z A�z'||attr.value!==copied.value||attr.ownerDocument!==target||copy.ownerDocument!==target||source.classList.value!=='')throw 'inert exact clone adoption';"#);run(&mut d,&mut f,&mut p,r"var imported=document.importNode(copy,true),nativeList=imported.relList;if(imported.ownerDocument!==document||imported.parentNode!==null||nativeList===copied||nativeList.value!==copied.value||imported.getAttributeNode('rel')===attr||copy.ownerDocument!==target)throw 'independent native token import';nativeList.add('independent');if(copied.contains('independent')||list.contains('independent'))throw 'token import source isolation';");p.state.node_limit=d.nodes.len();p.begin_job();run(&mut d,&mut f,&mut p,r#"var isolated=owner.createElement('area'),held=isolated.relList;held.value='X\ud800z';held.add('Y\udfffz');if(isolated.relList!==held||held.length!==2||held.value!=='X\ud800z Y\udfffz')throw 'inert source without main slots';var div=owner.createElement('div');"#);
for expression in ["div;","document.getElementById('label');"]{let Value::Host(owner)=p.runtime.execute(expression,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!()};let forged=script_class_list::area_rel_handle(owner);let before=(p.state.retained,p.state.dom_commits);let mut bridge=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state};assert!(!bridge.class_list_receiver(forged));assert!(bridge.class_list_get(forged,"length").is_err());assert!(bridge.class_list_set(forged,"value",Value::String("bad".into())).is_err());assert_eq!((bridge.state.retained,bridge.state.dom_commits),before);}
}
#[test]
fn area_rel_list_native_and_inert_refusals_preserve_records_and_recover(){for inert in [false,true]{for expression in [r#"list.value='long A\ud800z B\udfffz';"#,r#"list.add('longA\ud800z');"#,r#"output.relList='long A\ud800z B\udfffz';"#]{for mode in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var owner=document.implementation.createHTMLDocument('source'),output=owner.createElement('area');output.relList='seed';var list=output.relList,attr=output.getAttributeNode('rel'),watch=new MutationObserver(function(){});watch.observe(output,{attributes:true,attributeOldValue:true});"}else{"var output=document.getElementById('output'),list=output.relList;list.value='seed';var attr=output.getAttributeNode('rel'),watch=new MutationObserver(function(){});watch.observe(output,{attributes:true,attributeOldValue:true});"});p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());let limit=p.state.retained_limit;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=0,_=>p.state.execution_deadline=Some(Instant::now())};let e=p.runtime.execute(expression,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("bound")||e.contains("limit"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.state.retained_limit=limit;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(list.value!=='seed'||attr.value!=='seed'||watch.takeRecords().length)throw 'atomic refused token write';list.value='fresh';if(output.relList!==list||attr!==output.getAttributeNode('rel')||attr.value!=='fresh'||watch.takeRecords().length!==1)throw 'fresh exact token recovery';");}}}}
#[test]
fn area_rel_list_saved_child_origin_precedes_author_get_and_conversion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var output=document.getElementById('output'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var descriptor=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLAreaElement.prototype,'relList'),list=output.relList,calls=0;Object.defineProperty(output,'relList',{get:function(){calls++;return list;},configurable:true});descriptor.set.call(output,'A\ud800z');if(calls!==1||descriptor.get.call(output)!==list)throw 'saved child accessor';calls=0;"#);let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;p.set_location(&crate::navigation::address("https://foreign-output-tokens.test/",&crate::navigation::Location::home()).unwrap());p.begin_job();let e=p.runtime.execute("descriptor.set.call(output,{toString:function(){calls++;return 'bad';}});",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.set_location(&crate::navigation::address("https://area-rel-list.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls||list.value!=='A\\ud800z')throw 'origin ordering';descriptor.set.call(output,'fresh');if(calls!==1||list.value!=='fresh')throw 'fresh captured origin recovery';");}

#[test]
fn area_rel_list_getter_and_paid_reads_keep_identity_and_recover(){for inert in [false,true]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var owner=document.implementation.createHTMLDocument('source'),output=owner.createElement('area');output.relList='A\\ud800z B\\udfffz';var list=output.relList;"}else{"var output=document.getElementById('output');output.relList='A\\ud800z B\\udfffz';var list=output.relList;"});let Value::Host(owner)=p.runtime.execute("output;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!()};let retained=p.state.retained;let commits=p.state.dom_commits;let limit=p.state.retained_limit;p.state.retained_limit=retained;let Value::Host(list)=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.area_rel_list_get(owner).unwrap()else{panic!()};assert_eq!((p.state.retained,p.state.dom_commits),(retained,commits));for mode in 0..4{p.begin_job();p.state.retained_limit=limit;match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=retained,_=>p.state.execution_deadline=Some(Instant::now())};let e=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.class_list_get(list,"0").unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("limit"),"{e}");assert_eq!((p.state.retained,p.state.dom_commits),(retained,commits));}p.state.retained_limit=limit;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(output.relList!==list||list[0]!=='A\\ud800z'||list[1]!=='B\\udfffz')throw 'fresh paid token read recovery';");}}

#[test]
fn area_rel_list_native_inert_namespace_and_supported_processing_truth(){
 for inert in [false,true]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var owner=new Document(),output=owner.createElementNS('http://www.w3.org/1999/xhtml','t:area');output.rel='native';"}else{"var output=document.getElementById('output');output.rel='native';"});run(&mut d,&mut f,&mut p,r#"var list=output.relList,attr=output.getAttributeNode('rel'),watch=new MutationObserver(function(){});watch.observe(output,{attributes:true,attributeOldValue:true});output.setAttributeNS('urn:foreign','rel','foreign');output.setAttributeNS(null,'REL','upper');watch.takeRecords();if(list!==output.relList||list.value!=='native'||list.length!==1||list[0]!=='native')throw 'exact null namespace source';var calls=0;if(list.supports({toString:function(){calls++;return 'NOOPENER';}})||calls!==1||list.supports('noreferrer')||list.supports('opener')||list.supports('')||list.supports('unknown'))throw 'processing tokens require actual implementation';var caught=false;try{list.supports(Symbol('token'));}catch(e){caught=e instanceof TypeError;}if(!caught||watch.takeRecords().length||list.value!=='native'||attr!==output.getAttributeNode('rel'))throw 'supported lookup preserves source';list.add('A\ud800Z');if(attr.value!=='native A\ud800Z'||output.rel!==list.value||watch.takeRecords().length!==1||list===output.classList)throw 'separate exact live relation tokens';"#);}
}

#[test]
fn area_rel_list_preserves_unfinished_native_area_inherited_enumeration_refusal(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var output=document.getElementById('output'),held=output.relList;");let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;p.begin_job();let error=p.runtime.execute("for(var key in output){}",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("Inherited native Element enumeration is not implemented."),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.begin_job();run(&mut d,&mut f,&mut p,"held.add('fresh');if(output.relList!==held||output.rel!==held.value||!held.contains('fresh'))throw 'fresh token recovery after enumeration refusal';");
}
